<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Scam Shield</title>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-gray-100 min-h-screen flex items-center justify-center p-6">
  <div class="max-w-3xl w-full bg-white shadow-md rounded-lg p-6">
    <h1 class="text-2xl font-bold mb-4">Scam Shield</h1>
    <p class="text-sm text-gray-600 mb-4">Paste the internship/job offer below or upload a PDF/image. We'll check for common scam indicators.</p>

    <form id="offerForm" class="space-y-4">
      <div>
        <label class="block text-sm font-medium text-gray-700">Offer Text</label>
        <textarea id="offerText" name="offerText" rows="8" class="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></textarea>
      </div>

      <div>
        <label class="block text-sm font-medium text-gray-700">Upload File (PDF or image)</label>
        <input id="fileInput" name="file" type="file" accept="application/pdf,image/*" class="mt-1" />
      </div>

      <div>
        <button id="submitBtn" type="submit" class="inline-flex items-center px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700">Check Offer</button>
      </div>
    </form>

    <div id="result" class="mt-6 hidden bg-gray-50 p-4 rounded border">
      <h2 class="text-lg font-semibold">Result</h2>
      <div id="resultContent" class="mt-2 text-sm text-gray-800"></div>
    </div>
  </div>

  <script>
    const form = document.getElementById('offerForm');
    const resultDiv = document.getElementById('result');
    const resultContent = document.getElementById('resultContent');
    const submitBtn = document.getElementById('submitBtn');

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      submitBtn.disabled = true;
      submitBtn.textContent = 'Checking...';

      const offerText = document.getElementById('offerText').value;
      const fileInput = document.getElementById('fileInput');

      const formData = new FormData();
      formData.append('offer_text', offerText);
      if (fileInput.files.length > 0) {
        formData.append('file', fileInput.files[0]);
      }

      try {
        const resp = await fetch('http://127.0.0.1:8000/check-offer', {
          method: 'POST',
          body: formData
        });

        if (!resp.ok) {
          const err = await resp.json();
          resultContent.innerHTML = `<div class="text-red-600">Error: ${err.detail || resp.statusText}</div>`;
          resultDiv.classList.remove('hidden');
          return;
        }

        const data = await resp.json();

        // Render response
        resultContent.innerHTML = `
          <div class="mb-2"><strong>Legitimate:</strong> ${data.is_legitimate ? '<span class="text-green-700">Probably</span>' : '<span class="text-red-700">Probably Not</span>'}</div>
          <div class="mb-2"><strong>Confidence:</strong> ${data.confidence}%</div>
          <div class="mb-2"><strong>Red Flags:</strong><ul class="list-disc pl-5">${data.red_flags.map(f => `<li>${f}</li>`).join('')}</ul></div>
          <div class="mb-2"><strong>Recommendations:</strong><ul class="list-disc pl-5">${data.recommendations.map(r => `<li>${r}</li>`).join('')}</ul></div>
          <div class="mt-2"><strong>Analysis:</strong><div class="mt-1 text-sm text-gray-700">${data.analysis}</div></div>
        `;

        resultDiv.classList.remove('hidden');
      } catch (err) {
        console.error(err);
        resultContent.innerHTML = `<div class="text-red-600">Error: ${err.message}</div>`;
        resultDiv.classList.remove('hidden');
      } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Check Offer';
      }
    });
  </script>
</body>
</html>
